def is_valid_id(s):
    if len(s) != 10 or not s.isdigit():
        return False
    return s[0] in "12"

def password_score(p):
    score = 0
    if len(p) >= 8:
        score = score + 1
    if any(c.isdigit() for c in p):
        score = score + 1
    if any(c.isupper() for c in p):
        score = score + 1
    if any(c.islower() for c in p):
        score = score + 1
    return score

def summarize(*nums):
    return {
        "count": len(nums),
        "total": sum(nums),
        "max": max(nums) if nums else None,
    }
